// economy-engine 브라우저 번들 빌더.
// server/specialty.js + sim/economy-sim.js + sim/economy-sim-v2.js 를
// 브라우저용 단일 모듈(sim/economy-engine.browser.js)로 묶는다.
// require/module은 closure shim으로 처리, CLI(main)는 require.main 가드로 자동 비활성.
// 사용: node sim/build-econ-bundle.js  → 회귀검증: node sim/build-econ-bundle.js --check
const fs = require('fs');
const path = require('path');
const root = path.join(__dirname, '..');
const rd = f => fs.readFileSync(path.join(root, f), 'utf8').replace(/^#!.*\n/, '');

const era = rd('server/era.js');          // ★[2026-08-01] 시대 게이트 — specialty 가 이걸 파생한다. 빠지면 랩이 폴백표로 조용히 갈린다.
const specialty = rd('server/specialty.js');
const econ1 = rd('sim/economy-sim.js');
const econ2 = rd('sim/economy-sim-v2.js');
// ★[T400] 움집 공정·자재 정본(server/hut-stages.js) + 채당 정원(server/village-layout.js) — econ 이 T400_BUILD_ACT 켬일 때 집 자재를
//   이 두 정본에서 **유도**한다(사본 0). 끔이면 호출되지 않아 번들 결과 불변. village-layout 은 window.VillageLayout 을 덮지 않게 window 를 가린다.
const hut = rd('server/hut-stages.js');
const vlayout = rd('server/village-layout.js');
// ★[T419] 돌 쓰는 실물 정본(작업대 장비 재료 수 · 조잡한 석기) — econ 이 T419_STONE_REAL 켬일 때 단가를 유도한다(끔이면 안 불린다).
const stoneu = rd('server/stone-uses.js');
// ★[T435] 곳간 재료 정본(판자 12·돌 8) — econ 이 T435_GRANARY_ACT 켬일 때 곳간 원자재를 유도한다(끔이면 안 불린다).
const granst = rd('server/granary-stages.js');
// ★[T443] 노·숯가마·제련 연료 정본 — econ 이 T443_SMELT_FUEL 켬일 때 원석당 숯·숯당 통나무를 유도한다(끔이면 안 불린다).
const smeltu = rd('server/smelt-uses.js');
// ★[T471] 하루 길이 정본(`WORLD.dayLengthMs` · 단일 노브) — econ 숯가마(T452 `kilnBatchesPerDay`)가 읽는다. 없으면 번들에서 하루 0배치가 되어
//   랩이 CLI 와 갈린다(T471 에서 기본 켬이 되자 `--check` 가 7/8 불일치로 잡았다). window 를 가린다(설정 파일은 브라우저 전역을 안 만진다).
const zcfg = rd('server/zone-config.js');
// ★[T517] 무게 정본(`weights.kgOf` — 돌 한 단위 kg) — econ 주춧돌 팔(`T517_HUT_STONE`)이 kg 을 돌 단위로 바꾼다. specialty 뒤에 싣는다(그것을 require 한다).
const wts = rd('server/weights.js');
// ★[T570] 달력 정본(그레고리력 · 게임일 0 = 1년 3월 1일 · 계절 = 달) — econ `seasonOf`·`temperatureAt`·풍흉일·첫 계절 길이가 이걸 부른다.
//   **맨 앞에** 싣는다(econ 두 파일이 로드 때 require 한다). 빠지면 랩이 `{}` 를 받아 계절 함수가 없어 즉사한다.
const cal = rd('server/calendar.js');
// ★★[T648 2026-10-05] 작물 정본을 싣는다 — `server/crops.js` + 그 표 `crops.json` + 고증 표 `crop-cal.js` + 계절·달력 래퍼 `events.js`.
//   랩 밭 상태기(돌봄 일감 · 품질 감점)가 서버 T99 ②③ 휴면 술어(`crops.dormantAt` — 휴면 중 돌봄·품질 정지 · 다년생 휴면)를
//   **그 함수 그대로** 부른다(사본 0 · 랩은 `EconEngine.Crops`). crops.js 는 계절을 `events.seasonOf`·`calendarOf` 로 묻는다
//   (그 파일 머리 — "econ 정본 래퍼를 부르기만") ⇒ events.js 도 손대지 않고 싣는다. crop-cal.js 는 crops.js 의 T594 갈래(`calDaysOf`)가 늦게 부른다.
//   ⚠econ 결과 무변 — econ 은 `T100_FIELD_YIELD` 켬 팔에서만 crops 를 부른다(`seedFoodDays`) · `--check` 8/8.
//   ⚠weights.js 의 `require('./crops')` 도 이제 진짜 정본을 받는다(종전 `{}` — 작물 kg 갈래에서 던지던 자리 · econ 은 그 갈래를 안 지난다).
//   ⚠crops.js 의 늦은 짝 둘(`kcal` · `weather`)은 안 싣는다 — 랩이 부르는 `dormantAt` 은 그 둘을 안 탄다
//     (`weather` 는 없으면 "비 없음" 으로 도는 규약 · `hungerOf`·`payload` 는 `kcal` 이 없어 던진다 — 랩은 안 부른다).
const cropsData = rd('server/crops.json');
const cropcal = rd('server/crop-cal.js');
const events = rd('server/events.js');
const crops = rd('server/crops.js');
// ★★[T599 2026-10-03] 번들 안의 두 정본을 랩 쪽 코드에도 내놓는다 — 달력(`EconEngine.Calendar` · 랩 화면 날짜·달·철)과 마을 꼴(`EconEngine.Layout` ·
//   영토 목표·상한 `territoryTarget`). 이미 번들 안에 실려 있던 모듈 그대로다(사본 0 · econ 결과 무변 — `--check` 8/8). 랩이 손으로 옮겨 적던 식을 이 문으로 부른다.

const wrap = (name, body) =>
  `  modules[${JSON.stringify(name)}]=(function(){var module={exports:{}};var exports=module.exports;var require=req;\n${body}\n;return module.exports;})();\n`;

const wrapNoWin = (name, body) =>
  `  modules[${JSON.stringify(name)}]=(function(){var module={exports:{}};var exports=module.exports;var require=req;var window=undefined;\n${body}\n;return module.exports;})();\n`;

const bundle = `// AUTO-GENERATED by sim/build-econ-bundle.js — 직접 수정 금지.
// 소스: server/calendar.js + server/era.js + server/specialty.js + server/crops.json + server/crop-cal.js + server/events.js + server/crops.js + server/hut-stages.js + server/stone-uses.js + server/granary-stages.js + server/smelt-uses.js + server/zone-config.js + server/weights.js + server/village-layout.js + sim/economy-sim.js + sim/economy-sim-v2.js
;(function(root){
  var modules={};
  // ★process shim(2026-08-01) — 엔진 소스는 process.env 를 튜닝 손잡이로 읽는다(PEACE_W 등).
  //   브라우저엔 process 가 없어, 그 코드가 **처음 호출되는 순간** ReferenceError 로 터진다.
  //   실제로 터졌다: rational picker 에 전사 줄을 넣자 warriorTarget(process.env.PEACE_W)이
  //   랩에서 처음 호출돼 즉사했다 — CLI 하네스는 못 잡는 브라우저 전용 지뢰라 여기서 구조적으로 막는다.
  var process=(typeof root.process!=='undefined'&&root.process)?root.process:{env:{}};
  function req(p){ if(/crops[.]json$/.test(p))return modules.cropsData; if(/crop-cal/.test(p))return modules.cropcal; if(/(^|[/])events$/.test(p))return modules.events; if(/(^|[/])crops$/.test(p))return modules.crops; if(/calendar/.test(p))return modules.cal; if(/zone-config/.test(p))return modules.zcfg; if(/weights$/.test(p))return modules.wts; if(/hut-stages/.test(p))return modules.hut; if(/stone-uses/.test(p))return modules.stoneu; if(/granary-stages/.test(p))return modules.granst; if(/smelt-uses/.test(p))return modules.smeltu; if(/village-layout/.test(p))return modules.vlayout; if(/era/.test(p))return modules.era; if(/specialty/.test(p))return modules.specialty; if(/economy-sim-v2/.test(p))return modules.v2; if(/economy-sim/.test(p))return modules.v1; return {}; }
${wrapNoWin('cal', cal)}${wrap('era', era)}${wrap('specialty', specialty)}  modules["cropsData"]=${cropsData.trim()};
${wrapNoWin('cropcal', cropcal)}${wrapNoWin('events', events)}${wrapNoWin('crops', crops)}${wrapNoWin('wts', wts)}${wrap('hut', hut)}${wrap('stoneu', stoneu)}${wrap('granst', granst)}${wrap('smeltu', smeltu)}${wrapNoWin('zcfg', zcfg)}${wrapNoWin('vlayout', vlayout)}${wrap('v1', econ1)}${wrap('v2', econ2)}
  root.EconEngine=Object.assign({},modules.v1,modules.v2); root.EconEngine.Era=modules.era; root.EconEngine.Calendar=modules.cal; root.EconEngine.Layout=modules.vlayout; root.EconEngine.Crops=modules.crops;
})(typeof window!=='undefined'?window:globalThis);
`;

const outPath = path.join(root, 'sim/economy-engine.browser.js');
fs.writeFileSync(outPath, bundle);
console.log(`[build] economy-engine.browser.js 생성: ${(bundle.length / 1024).toFixed(0)} KB`);

// --check: 원본 모듈과 번들이 동일 시나리오서 정확히 일치하는지 회귀검증
if (process.argv.includes('--check')) {
  const Orig = require('./economy-sim-v2.js');
  delete require.cache[require.resolve(outPath)];
  require(outPath);
  const Bun = globalThis.EconEngine;
  const run = (Eng, seed, days) => {
    const w = Eng.createWorldV2({ seed, villageCount: 5, namePool: ['가','나','다','라','마'], infoRange: 5000, raidPer100: 0.005, picker: 'rational' });
    for (let d = 0; d < days; d++) Eng.tickWorldV2(w);
    return w.villages.map(v => `${v.name}:${v.npcs.length}/f${Math.floor(v.storage.food)}`).join(' ');
  };
  let pass = 0, fail = 0;
  for (const seed of [7, 42, 99, 1234]) for (const days of [150, 400]) {
    const ok = run(Orig, seed, days) === run(Bun, seed, days);
    ok ? pass++ : fail++;
  }
  console.log(`[check] 회귀검증 ${pass} 일치 / ${fail} 불일치` + (fail ? ' ❌' : ' ✅'));
  process.exit(fail ? 1 : 0);
}
